        "tracker_sheet_description_text": "Το φύλλο παρακολούθησης δείχνει τις ώρες που καταγράφηκαν μέσω του χρονομετρητή, μαζί με στιγμιότυπα οθόνης και τον συνολικό χρόνο που παρακολουθήθηκε.",
        "view_companies_switch_text": "Δείτε όλες τις εταιρείες με τις οποίες είστε συνδεδεμένοι και εναλλάξτε εύκολα μεταξύ τους επιλέγοντας μία.",
        "engage_team_real_time_text": "Συνεργαστείτε με τα μέλη της ομάδας σε πραγματικό χρόνο για γρήγορη λήψη αποφάσεων. Δημιουργήστε κανάλια και μοιραστείτε πληροφορίες μέσω συνημμένων, φωνητικών μηνυμάτων και κειμένων.",
        "real_time_notifications_text": "Μείνετε ενημερωμένοι με ειδοποιήσεις σε πραγματικό χρόνο σχετικά με τις δραστηριότητες έργου και εργασίας, όπως αναθέσεις εργασιών, αλλαγές καταστάσεων, σχόλια και προθεσμίες.",
        "address_specific_individuals_text": "Απευθυνθείτε απευθείας σε συγκεκριμένα άτομα μέσα στο σύστημα διαχείρισης έργου. Δείτε τις αναφορές που σχετίζονται με εργασίες, έργα ή συζητήσεις.",
        "access_personal_information_text": "Αποκτήστε πρόσβαση στις προσωπικές σας πληροφορίες, μαζί με ρυθμίσεις που σχετίζονται με εταιρείες, έργα, χρήστες και ασφάλεια, ανάλογα με το ρόλο του χρήστη σας.",
